-- BuildPropertiesBeamNative  -  property-panel section for BeamNative (directAccess plain Beam).

local W = require(script.Parent.Widgets)
local BuildPropertiesBeamNative = {}

-- Build the BeamNative section into the Properties scroll frame. Hidden by default;
-- SelectionHandler reveals when BeamNative items are selected.
function BuildPropertiesBeamNative.buildSection(scroll, refs, order)
	local beamNativeDefs = {
		{name = "Emission", rows = {
			{key="Enabled", label="Enabled", type="toggle"},
		}},
		{name = "Shape", rows = {
			{key="Attachment0", label="Attachment 0", type="path", config={kind="instance-picker", directProperty="Attachment0", validate="Attachment"}},
			{key="Attachment1", label="Attachment 1", type="path", config={kind="instance-picker", directProperty="Attachment1", validate="Attachment"}},
			{key="Width0", label="Width 0", type="input", default="1"},
			{key="Width1", label="Width 1", type="input", default="1"},
			{key="CurveSize0", label="CurveSize 0", type="input", default="0"},
			{key="CurveSize1", label="CurveSize 1", type="input", default="0"},
			{key="Segments", label="Segments", type="input", default="10"},
			{key="FaceCamera", label="FaceCamera", type="toggle"},
			{key="ZOffset", label="ZOffset", type="input", default="0"},
		}},
		{name = "Appearance", rows = {
			{key="Color", label="Color", type="color"},
			{key="Brightness", label="Brightness", type="input", default="1"},
			{key="Transparency", label="Transparency", type="graph"},
			{key="LightEmission", label="Light Emission", type="input", default="0"},
			{key="LightInfluence", label="Light Influence", type="input", default="0"},
		}},
		{name = "Texture", rows = {
			{key="Texture", label="Texture", type="input", default="", placeholder="rbxassetid:// or ID"},
			{key="TextureLength", label="Tex. Length", type="input", default="1"},
			{key="TextureSpeed", label="Tex. Speed", type="input", default="1"},
			{key="TextureMode", label="Tex. Mode", type="dropdown", options={"Stretch","Wrap","Static"}, default="Stretch"},
		}},
		{name = "Advanced", collapsed = true, rows = {
			{key="PreloadTexture", label="Preload Texture", type="toggle"},
		}},
	}
	refs.BeamNativeSection, refs.BeamNative = W.buildTypeSection(scroll, "BeamNatives", beamNativeDefs, order or 3)
	refs.BeamNativeSection.Visible = false
end

return BuildPropertiesBeamNative

-- BuildPropertiesReactor  -  property-panel section for the Reactor type.
-- Same pattern as BuildPropertiesRocks. Consumer: BuildProperties.buildProperties()
-- calls buildSection(scroll, refs) during its build.

local W = require(script.Parent.Widgets)
local BuildPropertiesReactor = {}

function BuildPropertiesReactor.buildSection(scroll, refs)
	-- After's and Break's option strings are TypeDataReactor.AFTER and BREAK;
	-- Populate/PopulateReactor hides the two time rows while After is Stay, and Piece Size while
	-- Break is None. Scatter is the recipe Modules/Scatter fills a region by: its two pickers
	-- write ObjectValues on the Reactor, its buttons are wired in PropertyInputsReactor.
	local reactorDefs = {
		{name = "Response", rows = {
			{key="Hold",       label="Hold", type="input", default="0"},
			{key="HoldSpread", label="Hold Spread", type="input", default="0.3"},
			{key="Group",      label="Group", type="input", default="", placeholder="none"},
			{key="MaxPieces",  label="Max Pieces", type="input", default="800"},
		}},
		{name = "Break", rows = {
			{key="Break",     label="Break", type="dropdown", options={"None","Blocks"}, default="None"},
			{key="PieceSize", label="Piece Size", type="input", default="2"},
			{key="Collapse",  label="Collapse", type="toggle"},
		}},
		{name = "Motion", rows = {
			{key="Gravity",     label="Gravity", type="input", default="196.2, 196.2", placeholder="min, max"},
			{key="Bounciness",  label="Bounciness", type="input", default="0.3, 0.5", placeholder="min, max"},
			{key="Friction",    label="Friction", type="input", default="0.5, 0.7", placeholder="min, max"},
			{key="TumbleSpeed", label="Tumble Speed", type="input", default="90, 360", placeholder="min, max"},
		}},
		{name = "After", rows = {
			{key="After",      label="After", type="dropdown", options={"Stay","Fade","Return"}, default="Stay"},
			{key="AfterDelay", label="Delay", type="input", default="2"},
			{key="AfterTime",  label="Time", type="input", default="1.5"},
		}},
		{name = "Scatter", collapsed = true, rows = {
			{key="ScatterSource",  label="Pieces", type="path", config={kind="instance-picker", objectValue="ScatterSource", acceptAnyInstance=true}},
			{key="ScatterRegion",  label="Region", type="path", config={kind="instance-picker", objectValue="ScatterRegion", validate="BasePart"}},
			{key="ScatterCount",   label="Count", type="input", default="40"},
			{key="ScatterSpacing", label="Spacing", type="input", default="1"},
			{key="ScatterTurn",    label="Turn", type="dropdown", options={"Upright","Any way"}, default="Upright"},
			{key="ScatterSize",    label="Size", type="input", default="0.8, 1.2", placeholder="min, max"},
			{key="ScatterSeed",    label="Seed", type="input", default="1"},
			{key="ScatterActions", label="Place", type="buttons", buttons={{key="Fill", text="Fill"}, {key="Clear", text="Clear"}}},
		}},
	}
	refs.ReactorSection, refs.Reactor = W.buildTypeSection(scroll, "Reactors", reactorDefs, 3)
	refs.ReactorSection.Visible = false
end

return BuildPropertiesReactor
